// Stage 1 output -> Stage 2 input: expand the segment array into a JSONL batch
const buffer = await this.helpers.getBinaryDataBuffer(0, 'minutes_file');
const segmented = JSON.parse(buffer.toString('utf8'));
const segments = segmented.items || [];
if (!segments.length) {
  throw new Error('Segmenter returned no items — check the AnalyzeDoc output');
}

// One JSONL line per segment. {"text": "..."} is the StructFlow input format.
const lines = segments.map((s) =>
  JSON.stringify({
    text: `[Agenda ${s.agenda_no}] ${s.agenda_title}\n\n${s.content}`,
  }),
);

const jsonl = Buffer.from(lines.join('\n'), 'utf8');
const binary = await this.helpers.prepareBinaryData(jsonl, 'segments.jsonl', 'application/jsonl');
return [{ json: { segment_count: segments.length }, binary: { segments_jsonl: binary } }];

// Stage 2 output (JSONL, one result per segment) -> one n8n item per decision/action
const buffer = await this.helpers.getBinaryDataBuffer(0, 'segments_jsonl');
const rows = [];

for (const line of buffer.toString('utf8').split('\n')) {
  const trimmed = line.trim();
  if (!trimmed) continue;
  let record;
  try {
    record = JSON.parse(trimmed);
  } catch (error) {
    continue;
  }
  if (record.$error) continue; // a failed segment does not break the others
  const output = record.output !== undefined ? record.output : record;
  for (const item of output.items || []) {
    rows.push({
      json: {
        agenda_no: output.agenda_no ?? '',
        agenda_title: output.agenda_title ?? '',
        item_type: item.item_type ?? '',
        item: item.item ?? '',
        owner: item.owner ?? '',
        due_date: item.due_date ?? '',
      },
    });
  }
}

if (!rows.length) {
  throw new Error('No decisions or action items were extracted');
}
return rows;
